def run_v117(args):
    old = sys.argv[:]
    try:
        sys.argv = ["mfp3_v117_embedded.py"]
        if args.full:
            sys.argv.append("--full")

        g = {
            "__name__": "mfp3_v117_embedded",
            "__file__": "<embedded:v1.17>",
            "__builtins__": __builtins__,
        }

        exec(
            compile(V117_SOURCE, g["__file__"], "exec"),
            g,
            g,
        )
        g["main"]()
    finally:
        sys.argv = old

