def now_utc():
    return datetime.now(timezone.utc).isoformat(timespec="seconds")

def fetch_bytes(url, timeout=60):
    req = urllib.request.Request(
        url,
        headers={"User-Agent": "Mozilla/5.0 MFP3-Research/1.18"},
    )
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read()

def cached_download(name, url, max_age_hours=24):
    path = CACHE / name

    if path.exists():
        age = (
            datetime.now(timezone.utc).timestamp()
            - path.stat().st_mtime
        ) / 3600.0

        if age <= max_age_hours:
            return path

    path.write_bytes(fetch_bytes(url))
    return path

def perf(ret):
    r = pd.Series(ret).fillna(0.0)

    if len(r) == 0:
        return {
            "total_return": 0.0,
            "cagr": 0.0,
            "sharpe": 0.0,
            "max_drawdown": 0.0,
            "ann_vol": 0.0,
        }

    curve = (1 + r).cumprod()
    total = float(curve.iloc[-1] - 1.0)
    years = max(len(r) / 252.0, 1 / 252.0)
    cagr = float(curve.iloc[-1] ** (1.0 / years) - 1.0)
    vol = float(r.std() * np.sqrt(252))
    sharpe = (
        float(r.mean() * 252 / vol)
        if vol > 1e-12
        else 0.0
    )
    dd = curve / curve.cummax() - 1.0

    return {
        "total_return": total,
        "cagr": cagr,
        "sharpe": sharpe,
        "max_drawdown": float(dd.min()),
        "ann_vol": vol,
    }

def utility(ret, turnover=None):
    p = perf(ret)
    t = (
        float(pd.Series(turnover).fillna(0).sum())
        if turnover is not None
        else 0.0
    )

    score = (
        p["sharpe"]
        + 0.35 * p["cagr"]
        - 0.55 * abs(p["max_drawdown"])
        - 0.010 * t
    )

    return score, p

def safe_name(s):
    return (
        str(s)
        .replace("^", "")
        .replace("=", "_")
        .replace("-", "_")
        .replace(".", "_")
        .lower()
    )

