def fred_series(series_id):
    url = (
        "https://fred.stlouisfed.org/graph/"
        f"fredgraph.csv?id={series_id}"
    )

    path = cached_download(
        f"fred_{series_id}.csv",
        url,
        max_age_hours=24,
    )

    df = pd.read_csv(path)
    idx = pd.to_datetime(
        df.iloc[:, 0],
        errors="coerce",
    )
    val = pd.to_numeric(
        df.iloc[:, -1],
        errors="coerce",
    )

    return pd.Series(
        val.to_numpy(),
        index=idx,
        name=series_id,
    ).dropna().sort_index()

def download_fred(status):
    out = {}

    for name, (sid, lag_days) in FRED_SERIES.items():
        try:
            s = fred_series(sid)

            # Conservative availability lag.
            s.index = (
                s.index
                + pd.to_timedelta(lag_days, unit="D")
            )

            out[name] = s

            status[f"FRED_{sid}"] = {
                "ok": True,
                "rows": len(s),
                "lag_days": lag_days,
            }

        except Exception as e:
            status[f"FRED_{sid}"] = {
                "ok": False,
                "error": repr(e)[:300],
            }

    return out

