CFTC_DATASET = "72hh-3qpy"
CFTC_COPPER_CODE = "085692"

def cftc_copper(status):
    base = (
        f"https://publicreporting.cftc.gov/resource/"
        f"{CFTC_DATASET}.csv"
    )

    params = {
        "$limit": "50000",
        "$where": (
            "cftc_contract_market_code='"
            + CFTC_COPPER_CODE
            + "'"
        ),
        "$order": "report_date_as_yyyy_mm_dd",
    }

    url = base + "?" + urllib.parse.urlencode(
        params,
        safe="'= ",
    )

    try:
        path = cached_download(
            "cftc_copper_disaggregated.csv",
            url,
            max_age_hours=24,
        )

        df = pd.read_csv(path)

        def find_col(*needles):
            for c in df.columns:
                low = str(c).lower()
                if all(n in low for n in needles):
                    return c
            return None

        date_col = find_col("report", "date")
        oi_col = find_col("open_interest", "all")

        mm_long = find_col("m_money", "long")
        mm_short = find_col("m_money", "short")

        prod_long = find_col("prod_merc", "long")
        prod_short = find_col("prod_merc", "short")

        swap_long = find_col("swap", "long")
        swap_short = find_col("swap", "short")

        needed = [
            date_col, oi_col,
            mm_long, mm_short,
            prod_long, prod_short,
            swap_long, swap_short,
        ]

        if any(c is None for c in needed):
            raise ValueError(
                "Columnas CFTC esperadas no encontradas."
            )

        idx = pd.to_datetime(
            df[date_col],
            errors="coerce",
        )

        oi = pd.to_numeric(
            df[oi_col],
            errors="coerce",
        ).replace(0, np.nan)

        def num(c):
            return pd.to_numeric(
                df[c],
                errors="coerce",
            )

        z = pd.DataFrame(
            index=idx,
        )

        z["cot_oi"] = oi.to_numpy()
        z["cot_mm_net_oi"] = (
            (num(mm_long) - num(mm_short))
            / oi
        ).to_numpy()

        z["cot_prod_net_oi"] = (
            (num(prod_long) - num(prod_short))
            / oi
        ).to_numpy()

        z["cot_swap_net_oi"] = (
            (num(swap_long) - num(swap_short))
            / oi
        ).to_numpy()

        z = z[
            ~z.index.isna()
        ].sort_index()

        # Tuesday positions generally become public later in the week.
        # +3 calendar days is conservative and avoids same-report-date leakage.
        z.index = (
            z.index + pd.Timedelta(days=3)
        )

        for c in [
            "cot_mm_net_oi",
            "cot_prod_net_oi",
            "cot_swap_net_oi",
        ]:
            z[f"{c}_chg4w"] = z[c].diff(4)

        status["CFTC_COPPER"] = {
            "ok": True,
            "rows": len(z),
            "contract_code": CFTC_COPPER_CODE,
        }

        return z

    except Exception as e:
        status["CFTC_COPPER"] = {
            "ok": False,
            "error": repr(e)[:400],
        }
        return pd.DataFrame()

