# Feature engineering
# ---------------------------------------------------------------------

def rolling_z(s, n):
    r = s.rolling(
        n,
        min_periods=max(20, n // 3),
    )
    return (
        (s - r.mean())
        / r.std().replace(0, np.nan)
    )

def market_block(s, prefix):
    x = pd.DataFrame(index=s.index)

    for n in [1, 5, 20, 60, 120]:
        x[f"{prefix}_ret{n}"] = s.pct_change(n)

    dr = s.pct_change()

    for n in [20, 60]:
        x[f"{prefix}_vol{n}"] = (
            dr.rolling(n).std()
            * np.sqrt(252)
        )

    x[f"{prefix}_z60"] = rolling_z(s, 60)
    x[f"{prefix}_z252"] = rolling_z(s, 252)

    return x

def level_block(s, prefix):
    x = pd.DataFrame(index=s.index)
    x[f"{prefix}_level"] = s
    x[f"{prefix}_chg5"] = s.diff(5)
    x[f"{prefix}_chg20"] = s.diff(20)
    x[f"{prefix}_z60"] = rolling_z(s, 60)
    x[f"{prefix}_z252"] = rolling_z(s, 252)
    return x

def build_asset_frame(
    asset,
    market,
    fred,
    cot,
    exo,
):
    usd = market[asset]
    idx = usd.index

    fx = (
        market["CLP=X"]
        .reindex(idx)
        .ffill(limit=5)
    )

    clp = usd * fx

    blocks = [
        market_block(clp, "self"),
        market_block(usd, "usd_asset"),
        market_block(fx, "usdclp"),
    ]

    predictor_returns = {}

    for t, s0 in market.items():
        if t == asset or t == "CLP=X":
            continue

        s = (
            s0.reindex(idx)
            .ffill(limit=5)
        )

        name = safe_name(t)

        if t == "^VIX":
            blocks.append(
                level_block(s, name)
            )
        else:
            blocks.append(
                market_block(s, name)
            )

        predictor_returns[name] = (
            s.pct_change()
        )

    # FRED levels already lagged conservatively.
    for name, s0 in fred.items():
        s = (
            s0.reindex(
                s0.index.union(idx)
            )
            .sort_index()
            .ffill()
            .reindex(idx)
        )

        blocks.append(
            level_block(
                s,
                "fred_" + name,
            )
        )

    # CFTC weekly positioning.
    if not cot.empty:
        cz = (
            cot.reindex(
                cot.index.union(idx)
            )
            .sort_index()
            .ffill()
            .reindex(idx)
        )

        cz.columns = [
            "cftc_" + safe_name(c)
            for c in cz.columns
        ]
        blocks.append(cz)

    # Exogenous monthly, shifted by one month.
    if not exo.empty:
        ez = (
            exo.reindex(
                exo.index.union(idx)
            )
            .sort_index()
            .ffill()
            .reindex(idx)
        )
        blocks.append(ez)

    X = pd.concat(
        blocks,
        axis=1,
    )

    own_ret = clp.pct_change()

    # Cross-market rolling correlations.
    for name, r in predictor_returns.items():
        for n in [20, 60]:
            X[
                f"corr_self_{name}_{n}"
            ] = own_ret.rolling(n).corr(
                r.reindex(idx)
            )

    # Mechanism-based spreads/interactions, still treated as candidates.
    def get(c):
        return (
            X[c]
            if c in X
            else pd.Series(np.nan, index=X.index)
        )

    X["rel_china_vs_spy20"] = (
        get("fxi_ret20") - get("spy_ret20")
    )
    X["rel_em_vs_spy20"] = (
        get("eem_ret20") - get("spy_ret20")
    )
    X["rel_copper_vs_gold20"] = (
        get("hg_f_ret20") - get("gc_f_ret20")
    )
    X["rel_copper_vs_usd20"] = (
        get("hg_f_ret20") - get("uup_ret20")
    )
    X["rel_risk_credit20"] = (
        get("hyg_ret20") - get("tlt_ret20")
    )

    X["price_clp"] = clp
    X["daily_ret_clp"] = own_ret

    # Signal t -> execute next session -> evaluate h sessions later.
    for h in HORIZONS:
        entry = clp.shift(-1)
        exit_ = clp.shift(-(h + 1))
        fwd = exit_ / entry - 1.0

        X[f"fwd_ret_{h}"] = fwd
        X[f"y_up_{h}"] = np.where(
            fwd.notna(),
            (fwd > 0).astype(float),
            np.nan,
        )

    return X

def feature_cols(df):
    excluded = {
        "price_clp",
        "daily_ret_clp",
    }

    for h in HORIZONS:
        excluded |= {
            f"fwd_ret_{h}",
            f"y_up_{h}",
        }

    return [
        c for c in df.columns
        if c not in excluded
    ]

# ---------------------------------------------------------------------
# Stable relationship discovery
# ---------------------------------------------------------------------

def rank_ic(a, b):
    z = pd.DataFrame(
        {"a": a, "b": b}
    ).dropna()

    if len(z) < 40:
        return np.nan

    return z["a"].rank().corr(
        z["b"].rank()
    )

def stable_singles(
    df,
    h,
    years,
):
    rows = []

    for f in feature_cols(df):
        ics = []

        for y in years:
            z = df[
                df.index.year == y
            ][[f, f"fwd_ret_{h}"]].dropna()

            if len(z) < MIN_DISCOVERY_OBS_YEAR:
                continue

            ic = rank_ic(
                z[f],
                z[f"fwd_ret_{h}"],
            )

            if pd.notna(ic):
                ics.append(float(ic))

        if len(ics) < 3:
            continue

        mean_ic = float(np.mean(ics))
        direction = (
            1.0
            if mean_ic >= 0
            else -1.0
        )

        consistency = float(
            np.mean([
                np.sign(x)
                == np.sign(mean_ic)
                for x in ics
                if x != 0
            ])
        ) if any(x != 0 for x in ics) else 0.0

        stability = (
            abs(mean_ic)
            * consistency
            / (1.0 + float(np.std(ics)))
        )

        if (
            consistency >= 2 / 3
            and abs(mean_ic) >= 0.012
        ):
            rows.append({
                "feature": f,
                "mean_ic": mean_ic,
                "direction": direction,
                "consistency": consistency,
                "stability": stability,
            })

    tab = pd.DataFrame(rows)

    if tab.empty:
        return tab

    return tab.sort_values(
        ["stability", "consistency"],
        ascending=False,
    ).head(MAX_SINGLE_FEATURES)

def robust_scale_fit(df, features):
    out = {}

    for f in features:
        s = pd.to_numeric(
            df[f],
            errors="coerce",
        )

        med = float(s.median())
        mad = float(
            (s - med).abs().median()
        )

        scale = 1.4826 * mad

        if (
            not np.isfinite(scale)
            or scale < 1e-8
        ):
            scale = float(s.std())

        if (
            not np.isfinite(scale)
            or scale < 1e-8
        ):
            scale = 1.0

        out[f] = (
            med,
            scale,
        )

    return out

def oriented_z(
    df,
    singles,
    scales,
):
    z = pd.DataFrame(index=df.index)

    for r in singles.itertuples():
        med, scale = scales[r.feature]

        raw = (
            pd.to_numeric(
                df[r.feature],
                errors="coerce",
            )
            - med
        ) / scale

        z[r.feature] = (
            raw * float(r.direction)
        ).clip(-5, 5)

    return z

def discover_interactions(
    discovery,
    h,
    singles,
    zdisc,
):
    if singles.empty:
        return pd.DataFrame()

    features = singles["feature"].tolist()
    single_map = dict(
        zip(
            singles["feature"],
            singles["mean_ic"].abs(),
        )
    )

    rows = []

    # top 10 only for pair search
    top = features[:10]

    for a, b in itertools.combinations(
        top,
        2,
    ):
        prod = zdisc[a] * zdisc[b]
        joint = np.minimum(
            zdisc[a],
            zdisc[b],
        )

        for kind, signal in [
            ("PRODUCT", prod),
            ("JOINT_MIN", joint),
        ]:
            yearly = []

            for y in sorted(
                discovery.index.year.unique()
            ):
                mask = (
                    discovery.index.year == y
                )

                ic = rank_ic(
                    signal[mask],
                    discovery.loc[
                        mask,
                        f"fwd_ret_{h}",
                    ],
                )

                if pd.notna(ic):
                    yearly.append(float(ic))

            if len(yearly) < 3:
                continue

            mean_ic = float(
                np.mean(yearly)
            )

            consistency = float(
                np.mean([
                    np.sign(x)
                    == np.sign(mean_ic)
                    for x in yearly
                    if x != 0
                ])
            ) if any(
                x != 0
                for x in yearly
            ) else 0.0

            best_single = max(
                single_map.get(a, 0.0),
                single_map.get(b, 0.0),
            )

            incremental = (
                abs(mean_ic)
                - best_single
            )

            if (
                consistency >= 2 / 3
                and abs(mean_ic) >= 0.018
                and incremental > -0.004
            ):
                rows.append({
                    "relation": (
                        f"{kind}({a},{b})"
                    ),
                    "kind": kind,
                    "a": a,
                    "b": b,
                    "mean_ic": mean_ic,
                    "direction": (
                        1.0
                        if mean_ic >= 0
                        else -1.0
                    ),
                    "consistency": consistency,
                    "incremental_ic": incremental,
                    "score": (
                        abs(mean_ic)
                        * consistency
                        * (
                            1.0
                            + max(
                                -0.25,
                                incremental * 5,
                            )
                        )
                    ),
                })

    tab = pd.DataFrame(rows)

    if tab.empty:
        return tab

    return tab.sort_values(
        ["score", "consistency"],
        ascending=False,
    ).head(MAX_RELATIONS)

def relationship_matrix(
    df,
    singles,
    interactions,
    scales,
):
    z = oriented_z(
        df,
        singles,
        scales,
    )

    out = pd.DataFrame(
        index=df.index,
    )

    # Singles remain candidate relations.
    for r in singles.itertuples():
        out[
            "SINGLE::" + r.feature
        ] = z[r.feature]

    for r in interactions.itertuples():
        if r.kind == "PRODUCT":
            s = (
                z[r.a] * z[r.b]
            )
        else:
            s = np.minimum(
                z[r.a],
                z[r.b],
            )

        out[
            "REL::" + r.relation
        ] = (
            s * float(r.direction)
        ).clip(-8, 8)

    return out

# ---------------------------------------------------------------------
# Models / nested temporal evaluation
# ---------------------------------------------------------------------

def model(alpha):
    return Pipeline([
        (
            "imp",
            SimpleImputer(
                strategy="median",
                add_indicator=True,
            ),
        ),
        (
            "sc",
            StandardScaler(),
        ),
        (
            "ridge",
            Ridge(alpha=alpha),
        ),
    ])

def strategy_returns(
    position,
    daily_ret,
):
    target = (
        pd.Series(
            position,
            index=daily_ret.index,
        )
        .fillna(0.0)
        .clip(0, 1)
    )

    # trade next session
    held = target.shift(1).fillna(0.0)

    turnover = (
        held.diff().abs()
        .fillna(held.abs())
    )

    net = (
        held
        * daily_ret.fillna(0.0)
        - turnover * ONE_WAY_COST
    )

    return net, held, turnover

def prediction_to_position(
    pred,
    train_target,
):
    scale = float(
        pd.Series(
            train_target
        ).std()
    )

    if (
        not np.isfinite(scale)
        or scale < 1e-5
    ):
        scale = 0.02

    score = np.tanh(
        pd.Series(pred)
        / scale
    )

    # long-only, from 0 to 1
    return (
        0.50
        + 0.50 * score
    ).clip(0, 1)

def evaluate_candidate(
    train,
    validation,
    rel_train,
    rel_val,
    h,
    alpha,
):
    target = f"fwd_ret_{h}"

    valid_cols = [
        c for c in rel_train.columns
        if (
            rel_train[c].notna().mean() >= 0.60
            and rel_val[c].notna().mean() >= 0.40
        )
    ]

    if len(valid_cols) < 3:
        return None

    tr = pd.concat(
        [
            rel_train[valid_cols],
            train[[target]],
        ],
        axis=1,
    ).dropna(
        subset=[target]
    )

    if len(tr) < 400:
        return None

    m = model(alpha)
    m.fit(
        tr[valid_cols],
        tr[target],
    )

    pred = pd.Series(
        m.predict(
            rel_val[valid_cols]
        ),
        index=validation.index,
    )

    pos = prediction_to_position(
        pred,
        tr[target],
    )

    net, held, turnover = strategy_returns(
        pos,
        validation["daily_ret_clp"],
    )

    u, p = utility(
        net,
        turnover,
    )

    return {
        "horizon": h,
        "alpha": alpha,
        "utility": u,
        "perf": p,
        "columns": valid_cols,
    }

def evaluate_year(
    asset,
    df,
    test_year,
):
    discovery_years = [
        test_year - 5,
        test_year - 4,
        test_year - 3,
    ]
    validation_years = [
        test_year - 2,
        test_year - 1,
    ]

    required = (
        discovery_years
        + validation_years
        + [test_year]
    )

    for y in required:
        if (
            np.sum(
                df.index.year == y
            )
            < MIN_DISCOVERY_OBS_YEAR
        ):
            return None

    discovery = df[
        df.index.year.isin(
            discovery_years
        )
    ].copy()

    validation = df[
        df.index.year.isin(
            validation_years
        )
    ].copy()

    test = df[
        df.index.year == test_year
    ].copy()

    candidates = []

    for h in HORIZONS:
        singles = stable_singles(
            discovery,
            h,
            discovery_years,
        )

        if len(singles) < 4:
            continue

        scales = robust_scale_fit(
            discovery,
            singles["feature"].tolist(),
        )

        zdisc = oriented_z(
            discovery,
            singles,
            scales,
        )

        inter = discover_interactions(
            discovery,
            h,
            singles,
            zdisc,
        )

        rel_disc = relationship_matrix(
            discovery,
            singles,
            inter,
            scales,
        )

        rel_val = relationship_matrix(
            validation,
            singles,
            inter,
            scales,
        )

        for alpha in RIDGE_ALPHAS:
            e = evaluate_candidate(
                discovery,
                validation,
                rel_disc,
                rel_val,
                h,
                alpha,
            )

            if e is not None:
                e["singles"] = singles
                e["interactions"] = inter
                e["scales"] = scales
                candidates.append(e)

    if not candidates:
        return None

    best = max(
        candidates,
        key=lambda x: x["utility"],
    )

    h = best["horizon"]

    # Relationships remain frozen from discovery.
    pretest = df[
        df.index.year < test_year
    ].copy()

    rel_pre = relationship_matrix(
        pretest,
        best["singles"],
        best["interactions"],
        best["scales"],
    )

    rel_test = relationship_matrix(
        test,
        best["singles"],
        best["interactions"],
        best["scales"],
    )

    cols = [
        c for c in best["columns"]
        if c in rel_pre
        and c in rel_test
    ]

    target = f"fwd_ret_{h}"

    # Remove observations whose label would cross into test period.
    cutoff = (
        test.index.min()
        - pd.tseries.offsets.BDay(
            h + 1
        )
    )

    tr_mask = (
        pretest.index <= cutoff
    )

    tr = pd.concat(
        [
            rel_pre.loc[
                tr_mask,
                cols,
            ],
            pretest.loc[
                tr_mask,
                [target],
            ],
        ],
        axis=1,
    ).dropna(
        subset=[target]
    )

    if len(tr) < 500:
        return None

    m = model(
        best["alpha"]
    )

    m.fit(
        tr[cols],
        tr[target],
    )

    pred = pd.Series(
        m.predict(
            rel_test[cols]
        ),
        index=test.index,
    )

    pos = prediction_to_position(
        pred,
        tr[target],
    )

    net, held, turnover = strategy_returns(
        pos,
        test["daily_ret_clp"],
    )

    p = perf(net)

    return {
        "asset": asset,
        "test_year": test_year,
        "horizon": h,
        "alpha": best["alpha"],
        "validation_utility": best["utility"],
        "validation_sharpe": best["perf"]["sharpe"],
        "future_return": p["total_return"],
        "future_sharpe": p["sharpe"],
        "future_drawdown": p["max_drawdown"],
        "n_singles": len(
            best["singles"]
        ),
        "n_interactions": len(
            best["interactions"]
        ),
        "singles": best["singles"],
        "interactions": best["interactions"],
        "daily_ret": net,
        "position": held,
        "prediction": pred,
        "test_frame": test,
    }

# ---------------------------------------------------------------------
# Walk-forward engine
# ---------------------------------------------------------------------

def run_asset(
    asset,
    df,
):
    yearly = []
    relation_rows = []
    daily_parts = []

    latest_year = int(
        df.index.max().year
    )

    for year in range(
        FIRST_TEST_YEAR,
        latest_year + 1,
    ):
        res = evaluate_year(
            asset,
            df,
            year,
        )

        if res is None:
            continue

        yearly.append({
            "asset": asset,
            "test_year": year,
            "horizon": res["horizon"],
            "alpha": res["alpha"],
            "validation_utility":
                res["validation_utility"],
            "validation_sharpe":
                res["validation_sharpe"],
            "future_return":
                res["future_return"],
            "future_sharpe":
                res["future_sharpe"],
            "future_drawdown":
                res["future_drawdown"],
            "n_singles":
                res["n_singles"],
            "n_interactions":
                res["n_interactions"],
        })

        for r in res[
            "singles"
        ].itertuples():
            relation_rows.append({
                "asset": asset,
                "test_year": year,
                "horizon": res["horizon"],
                "type": "SINGLE",
                "relationship": r.feature,
                "ic": r.mean_ic,
                "consistency":
                    r.consistency,
                "score": r.stability,
            })

        for r in res[
            "interactions"
        ].itertuples():
            relation_rows.append({
                "asset": asset,
                "test_year": year,
                "horizon": res["horizon"],
                "type": r.kind,
                "relationship":
                    r.relation,
                "ic": r.mean_ic,
                "consistency":
                    r.consistency,
                "score": r.score,
            })

        z = pd.DataFrame(
            index=res[
                "test_frame"
            ].index
        )

        z["asset"] = asset
        z["test_year"] = year
        z["horizon"] = res["horizon"]
        z["prediction"] = (
            res["prediction"]
        )
        z["position"] = (
            res["position"]
        )
        z["strategy_ret"] = (
            res["daily_ret"]
        )
        z["daily_ret_clp"] = (
            res["test_frame"][
                "daily_ret_clp"
            ]
        )

        daily_parts.append(z)

        print(
            f"  {asset} {year}: "
            f"H={res['horizon']} | "
            f"relations={res['n_singles']}+{res['n_interactions']} | "
            f"futuro={res['future_return']:+.2%} | "
            f"Sharpe={res['future_sharpe']:.2f}"
        )

    return (
        pd.DataFrame(yearly),
        pd.DataFrame(relation_rows),
        pd.concat(
            daily_parts
        ).sort_index()
        if daily_parts
        else pd.DataFrame(),
    )

# ---------------------------------------------------------------------
# Relationship portfolio
# ---------------------------------------------------------------------

def relationship_portfolio(
    daily,
    frames,
):
    idx = pd.DatetimeIndex(
        sorted(
            daily.index.unique()
        )
    )

    strategy = pd.Series(
        0.0,
        index=idx,
    )

    benchmark = pd.Series(
        0.0,
        index=idx,
    )

    for asset in TARGETS:
        z = daily[
            daily["asset"] == asset
        ]

        sr = (
            z["strategy_ret"]
            .groupby(z.index)
            .last()
            .reindex(idx)
            .fillna(0.0)
        )

        strategy += (
            MAX_ASSET_WEIGHT * sr
        )

        benchmark += (
            MAX_ASSET_WEIGHT
            * frames[asset][
                "daily_ret_clp"
            ]
            .reindex(idx)
            .fillna(0.0)
        )

    out = pd.DataFrame(
        index=idx
    )

    out[
        "relationship_ret"
    ] = strategy

    out[
        "benchmark_ret"
    ] = benchmark

    out[
        "capital_relationship"
    ] = (
        INITIAL_CAPITAL
        * (1 + strategy).cumprod()
    )

    out[
        "capital_benchmark"
    ] = (
        INITIAL_CAPITAL
        * (1 + benchmark).cumprod()
    )

    return out

# ---------------------------------------------------------------------
# Adaptive blend with v1.14
# ---------------------------------------------------------------------

def monthly_firsts(index):
    s = pd.Series(
        np.arange(len(index)),
        index=index,
    )

    return set(
        s.groupby(
            [index.year, index.month]
        ).head(1).index
    )

def blend_utility(frame, relation_weight):
    ret = (
        (1 - relation_weight)
        * frame["fusion_ret"]
        + relation_weight
        * frame["relationship_ret"]
    )

    return utility(ret)[0]

def adaptive_relationship_fusion(
    relationship_port,
):
    if not V14_DAILY.exists():
        return pd.DataFrame()

    v14 = pd.read_csv(
        V14_DAILY,
        index_col=0,
        parse_dates=True,
    ).sort_index()

    v14.index = pd.to_datetime(
        v14.index
    ).tz_localize(None)

    common = (
        relationship_port.index
        .intersection(v14.index)
    )

    if len(common) < 500:
        return pd.DataFrame()

    x = pd.DataFrame(
        index=common
    )

    x[
        "relationship_ret"
    ] = relationship_port.loc[
        common,
        "relationship_ret",
    ]

    x[
        "benchmark_ret"
    ] = relationship_port.loc[
        common,
        "benchmark_ret",
    ]

    x["fusion_ret"] = v14.loc[
        common,
        "fusion_ret",
    ]

    x["v17_ret"] = v14.loc[
        common,
        "v17_ret",
    ]

    firsts = monthly_firsts(
        x.index
    )

    weights = pd.Series(
        0.0,
        index=x.index,
    )

    current = 0.0

    for i, dt in enumerate(
        x.index
    ):
        if i < 252:
            weights.loc[dt] = current
            continue

        if dt in firsts:
            hist = x.iloc[:i]

            rows = []

            for window in BLEND_WINDOWS:
                z = hist.tail(
                    window
                )

                if len(z) < 200:
                    continue

                for w in RELATION_BLEND_WEIGHTS:
                    rows.append({
                        "window": window,
                        "weight": w,
                        "utility":
                            blend_utility(
                                z,
                                w,
                            )
                            - 0.02 * w,
                    })

            tab = pd.DataFrame(
                rows
            )

            if len(tab):
                top = tab.sort_values(
                    "utility",
                    ascending=False,
                ).head(3)

                scores = (
                    top["utility"]
                    .to_numpy()
                )

                scores = (
                    scores
                    - np.max(scores)
                )

                prob = np.exp(
                    scores / 0.08
                )
                prob /= prob.sum()

                target = float(
                    np.sum(
                        top["weight"]
                        .to_numpy()
                        * prob
                    )
                )

                # shrink new engine toward zero until it proves itself
                current = (
                    0.70 * target
                    + 0.30 * current
                )

        weights.loc[dt] = current

    x[
        "relationship_weight"
    ] = weights

    x[
        "v14_weight"
    ] = 1.0 - weights

    x[
        "relationship_fusion_ret"
    ] = (
        x["v14_weight"]
        * x["fusion_ret"]
        + x["relationship_weight"]
        * x["relationship_ret"]
    )

    x[
        "capital_relationship_fusion"
    ] = (
        INITIAL_CAPITAL
        * (
            1
            + x["relationship_fusion_ret"]
        ).cumprod()
    )

    return x

# ---------------------------------------------------------------------
# Metrics/current
# ---------------------------------------------------------------------

def build_metrics(
    engine_port,
    fusion,
):
    rows = []

    if len(fusion):
        rows.append({
            "name":
                "RELATIONSHIP_FUSION_CHALLENGER",
            **perf(
                fusion[
                    "relationship_fusion_ret"
                ]
            ),
        })

        rows.append({
            "name":
                "V14_ADAPTIVE_FUSION_REFERENCE",
            **perf(
                fusion[
                    "fusion_ret"
                ]
            ),
        })

        rows.append({
            "name":
                "V17_REFERENCE_COMMON_WINDOW",
            **perf(
                fusion[
                    "v17_ret"
                ]
            ),
        })

        rows.append({
            "name":
                "RELATIONSHIP_ENGINE_REFERENCE",
            **perf(
                fusion[
                    "relationship_ret"
                ]
            ),
        })

        rows.append({
            "name":
                "BENCHMARK_COMMON_WINDOW",
            **perf(
                fusion[
                    "benchmark_ret"
                ]
            ),
        })

    else:
        rows.append({
            "name":
                "RELATIONSHIP_ENGINE_REFERENCE",
            **perf(
                engine_port[
                    "relationship_ret"
                ]
            ),
        })

        rows.append({
            "name":
                "BENCHMARK_COMMON_WINDOW",
            **perf(
                engine_port[
                    "benchmark_ret"
                ]
            ),
        })

    return pd.DataFrame(
        rows
    )

def current_relationships(
    yearly,
    relations,
):
    if yearly.empty:
        return pd.DataFrame()

    latest = int(
        yearly["test_year"].max()
    )

    rows = []

    for asset in TARGETS:
        y = yearly[
            (yearly["asset"] == asset)
            & (
                yearly["test_year"]
                == latest
            )
        ]

        if y.empty:
            continue

        r = y.iloc[-1]

        rel = relations[
            (relations["asset"] == asset)
            & (
                relations["test_year"]
                == latest
            )
            & (
                relations["horizon"]
                == r["horizon"]
            )
        ].copy()

        rel["abs_score"] = (
            rel["score"].abs()
        )

        rel = rel.sort_values(
            "abs_score",
            ascending=False,
        ).head(8)

        rows.append({
            "asset": asset,
            "research_year": latest,
            "horizon":
                int(r["horizon"]),
            "historical_future_return":
                float(
                    r["future_return"]
                ),
            "historical_future_sharpe":
                float(
                    r["future_sharpe"]
                ),
            "top_relationships":
                " | ".join(
                    f"{x.relationship} "
                    f"[IC={x.ic:+.3f}]"
                    for x in rel.itertuples()
                ),
        })

    return pd.DataFrame(
        rows
    )

